package com.fakelegacy.order.service;

import java.time.LocalDateTime;
import java.util.List;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import com.fakelegacy.order.domain.Order;
import com.fakelegacy.order.repo.OrderRepository;

@Component
public class OrderExpiryJob {

    private static final Logger log = LoggerFactory.getLogger(OrderExpiryJob.class);

    @Autowired
    private OrderRepository orders;

    @Autowired
    private OrderManager orderManager;

    // unpaid orders hold their reservation for 15 minutes (24 hours when waiting for review)
    @Scheduled(initialDelay = 30000, fixedDelay = 30000)
    public void expireUnpaidOrders() {
        List<Order> late = orders.findByStatusInAndExpiresAtBefore(List.of("VALIDATED", "PENDING_REVIEW"),
                LocalDateTime.now());
        for (Order o : late) {
            log.info("order {} expired", o.getReference());
            orderManager.markExpired(o);
        }
    }
}
